mod solution;

fn main() {
    let cases = [
    (r#"text=ahishers patterns=[he,she,his,hers]"#, r#"4"#),
    (r#"text=aaaa patterns=[a,aa]"#, r#"7"#),
    (r#"
text=aaaa patterns=[a,aa]
"#, r#"7"#),
    (r#"  
text=ahishers patterns=[he,she,his,hers]
  "#, r#"4"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS aho-corasick");
}
